func (l *xloc) String() string {
	if l == nil || l.Value == nil {
		return ""
	}
	return l.Value.String()
}

func _loc(v Value, p Pos) Value {
	if t := v.Pos(); t == p {
		return v
	} else {
		return &loc{v, p}
	}
}

