// barefile reduces file lookups, it works like an alias of a File.
type barefile struct{ Value ; file *file }
func (_ *barefile) kind() Kind { return KindBarefile }

func barefilize(ctx Context, targets ...Value) []Value {
    var project = _project(ctx)
    for i, target := range targets {
        if patterned(ctx,target) { continue }
        switch t := target.(type) {
        case *word:
            if f := project.file(ctx, t.s); f != nil {
                targets[i] = &barefile{ target, f }
                f.pos = target.Pos()
            }
        case *compound, *path:
            if patterned(ctx,t) /* || t.expandable(ctx) */ /* || refdef(ctx, t, DefArg) */ {//, expandDef2
                break
            } else if f := project.file(ctx, __string(ctx, t)); f != nil {
                targets[i] = &barefile{ target, f }
                f.pos = target.Pos()
            }
        case *argumented:
            t.Value = barefilize(ctx, t.Value)[0]
            t.args  = barefilize(ctx, t.args...)
        }
    }
    return targets
}
func exp_barefilize(ctx Context, targets ...Value) (res []Value) {
    var maps []matched_filemap
	var proj = _project(ctx)
    for _, target := range targets {
        if !patterned(ctx,target) {
            maps = append(maps, unmap_files(ctx, proj, target, nil)...)
        }
    }
    for _, f := range select_files(ctx, maps) { res = append(res, f) }
    return
}

var ErrBadPattern = errors.New("syntax error in pattern")

type path struct{ elements }
func (_ *path) kind() Kind { return KindPath }
func (p *path) String() (s string) {
    var n int
    for i, elem := range p.elems {
        if t := elem.String(); 0 < i {
            s += pathSep + t
            n += 1
        } else if t != "" {
            s += t
        } else if len(p.elems) == 1 {
            s += pathSep
            n += 1
        }
    }

    if n == 0 { s = "{path "+s+"}" }
    return
}
func (p *path) isAbs() bool { x, y := p.elems[0].(*punct); return y && x.token == PROOT }
func _pathStr(ctx Context, str string) *path { return &path{elements{splitPathStr(ctx, str)}} }
func _pathSym(pos Pos, sym Symbol) Value {
	if sym == symEmpty {
		return nil
	}

	// A path symbol is a flatten sequence, e.g. [foobar / a . def . am]
	seq := getSymSeq(sym)
	if len(seq) == 0 {
		return _word(pos, sym)
	}

	var p = new(path)
	var current []Value

	for i, part := range seq {
		if part == symSlash {
			if l := len(current); l > 1 {
				p.elems = append(p.elems, &compound{elements{current}})
			} else if l == 1 {
				p.elems = append(p.elems, current[0])
			}

			// THE DOD FIX: Restore Absolute Roots and Trailing Slashes!
			// If the slash is at index 0, it is PROOT (absolute path).
			// If the slash is at the very end, it is PTAIL (directory boundary).
			if i == 0 {
				p.elems = append(p.elems, &punct{valbase{pos}, PROOT})
			} else if i == len(seq)-1 {
				p.elems = append(p.elems, &punct{valbase{pos}, PTAIL})
			}

			current = nil // Reset and detach memory for the next directory
		} else if part != symEmpty {
			current = append(current, _word(pos, part))
		}
	}
	
	// Flush the final segment
	if current != nil {
		if l := len(current); l > 1 {
			p.elems = append(p.elems, &compound{elements{current}})
		} else if l == 1 {
			p.elems = append(p.elems, current[0])
		}
	}

	if len(p.elems) == 1 {
		return p.elems[0]
	}
	return p // can be empty path (e.g., if sym was exclusively symEmpty)
}

func to_file(v Value) (x *file, y bool) {
    if x, y = v.(*file); !y {
        switch t := v.(type) {
		case     *loc: x, y = to_file(t.Value)
		case    *xloc: x, y = to_file(t.Value)
        case fullname: x, y = to_file(t.Value)
        case fullfile: x, y = t.file, true
        case *list: if t.len() == 1 { x, y = to_file(t.elems[0]) }
        }
    }
    return
}

