// ResolvePosition converts a compact AST 'Pos' back into a human-readable 'Position'
func ResolvePosition(ctx Context, v Value) Position {
	if v == nil {
		return Position{}
	}

	// 1. Runtime / Synthetic Position Escape Hatch
	// If the value is explicitly wrapped in an external location (*xloc), use its fat struct!
	if l, ok := v.(*xloc); ok {
		return l.pos
	}

	// (Optional but robust) Check if any other node implements the fat Position interface
	if p, ok := v.(interface{ Position() Position }); ok {
		if pos := p.Position(); pos.valid() {
			return pos
		}
	}

	// 2. Parse-Time Position Resolution
	pos := v.Pos() // The compact integer
	if !pos.valid() {
		return Position{} // NoPos
	}

	// Safely retrieve the fset from the universe
	if u := _universe(ctx); u != nil && u.fset != nil {
		return u.fset.Position(pos)
	}

	return Position{}
}

func _universe(c Context) *universe { return cast[*universe](c) }

type universe struct {
    diagnostic
    commandline

    *scope
    *globe

	launchTime time.Time

    fset *fileset

    prefix  string // FIXME: prefix for distribution
	workdir Symbol // FIXME: restore workdir for loading
    paths   searchlist

    statmutex sync.Mutex
    statcache map[Symbol]*filebase // file.fullname() -> File

    hooks hooks
}

func (ctx *universe) String() string { return "universe" }

func (ctx *universe) _position() (p Position) {
    if ctx.globe != nil && ctx.globe.main != nil && ctx.fset != nil {
		p = ctx.fset.Position(ctx.globe.main.pos)
    } else {
		p.Filename, p.Line, p.Column = symBaseWorkDir, 0, 0
	}
    return
}

func (ctx *universe) trimFileSpec(c Context, spec Symbol) Symbol {
	if spec == symEmpty {
		return symEmpty
	}

	// 1. Emulate strings.ReplaceAll(spec, "../", "")
	seq := getSymSeq(spec)
	hasDotDot := false
	for _, s := range seq {
		if s == symDotDot {
			hasDotDot = true
			break
		}
	}

	if hasDotDot {
		clean := make([]Symbol, 0, len(seq))
		for i := 0; i < len(seq); i++ {
			if seq[i] == symDotDot {
				// Skip the symDotDot AND the trailing slash (just like ReplaceAll)
				if i+1 < len(seq) && seq[i+1] == symSlash {
					i++ 
				}
				continue
			}
			clean = append(clean, seq[i])
		}
		spec = internSeq(clean)
	}

	// 2. Zero-allocation helper to match and trim "dirSym + symSlash"
	trimDirSlash := func(target Symbol, dirSym Symbol) Symbol {
		if dirSym == symEmpty { return target }
		
		dirSeq := getSymSeq(dirSym)
		if len(dirSeq) == 0 { return target }
		
		tSeq := getSymSeq(target)
		
		// If dir already inherently ends in a slash, use standard prefix match
		if dirSeq[len(dirSeq)-1] == symSlash {
			if __symHasPrefix(target, dirSym) {
				return __symTrimPrefix(target, dirSym)
			}
			return target
		}
		
		// O(1) Lookahead Match: Does target start with dir AND have a trailing slash?
		if len(tSeq) > len(dirSeq) && tSeq[len(dirSeq)] == symSlash {
			match := true
			for i := 0; i < len(dirSeq); i++ {
				if tSeq[i] != dirSeq[i] {
					match = false
					break
				}
			}
			if match {
				// Trim both the dir sequence and the trailing slash!
				return internSeq(tSeq[len(dirSeq)+1:])
			}
		}
		return target
	}

	// 3. Check and trim paths (now operating purely on Symbols!)
	for _, s := range ctx.paths {
		newSpec := trimDirSlash(spec, s)
		if newSpec != spec {
			spec = newSpec
			break
		}
	}

	// 4. Check and trim workdir (now operating purely on Symbols!)
	return trimDirSlash(spec, symBaseWorkDir)
}

func (u *universe) do(ctx Context, op any) (res any) {
    switch t := op.(type) {
	case inner_cast: return &u.diagnostic
	case dynamic_cast: return t.ctx(ctx, &u.diagnostic)
    case get_pos: return NoPos //Position{ Filename: symBaseWorkDir }
	case get_fatpos:
		var p Position
		if u.fset != nil && t.p.valid() { p = u.fset.Position(t.p) } // FIX: Use the receiver 'ctx'
		return p

    case get_scope: if u.scope != nil { return u.scope }
    case get_project: if u.globe != nil { return u.globe.main }
    case exec_noop: if u.noExec { return u.noExec }
	case is_test_mode: if u.testMode { return true }

	case declared_project:
		if t.project == nil {
			erro(ctx, "declared nil project", callstack{stop:"smart.Main"})
			return
		}

		// RULE 1: ALL projects must be cached!
		// If we don't cache them, `use1` will think they failed to load.
		if p, ok := u.globe.loaded[t.absPath]; !ok {
			if false { debug(ctx, "%v %v", t.absPath, t.project) }
			u.globe.loaded[t.absPath] = t.project
		} else if p != t.project {
			erro(ctx, "re-declared project: %v → %v", p.name, t.name,
				trace_ctx{100}, callstack{stop:"smart.Main"})
		}

		// RULE 2: ONLY the entry-point gets to be 'main'!
		// The Host project ruthlessley claims the crown because its absPath == workdir.
		if t.absPath == u.workdir {
			var properName = t.name
			for s := t.scope; s != nil && s != u.globe.scope && s.project != nil; s = s.outer {
				if s.project.name == symAt { properName = symEmpty; break }
			}
			switch properName {
			case symEmpty, symAt, symTilde, symConfigure, symDotConfigure:
				// Special projects can't be the "main"!
			default:
				u.globe.main = t.project // The Main Project is the Working Directory

				// The "globe.pairs" defines arguments from `compiler.parseArgs`;
				// we define them in the main scope `p.scope` (vs. `p.project.scope`) if not "~".
				for _, p := range u.globe.pairs {
					switch k := p.key.(type) {
					case *word, *compound, flag:
						t.scope.def(ctx, defDecl, __symbol(ctx, k), p.val)
					default:
						erro(ctx, "%v: unknown target: %v : %v", t.name, p, ts(p,ctx),
							callstack{stop:"smart.Main"})
					}
				}
			}
		}

	case cachestat:
		u.statmutex.Lock()
		base, exists := u.statcache[t.cleanFullname]
		if !exists {
			// Explicitly map fields to avoid zero-initialization errors
			base = &filebase{stub: filestub{dir: t.dir, sub: t.sub, name: t.name}}
			base.stub.other = &base.stub
			u.statcache[t.cleanFullname] = base
		}
		u.statmutex.Unlock() // INSTANTLY drop the global lock!
		return base

	case search_path:
		if t.sym != symEmpty {
			for _, baseSym := range u.paths {
				// 1. Join paths entirely in the integer/Symbol domain
				joinedSym := __symPathJoin(baseSym, t.sym)
				
				// 2. Prepend workdir if the base wasn't absolute
				if !__symIsAbs(baseSym) {
					joinedSym = __symPathJoin(symBaseWorkDir, joinedSym)
				}
				
				// 3. Hit the VFS Cache instead of the physical disk!
				// _stat handles the cache lookup, and only hits the disk if unseen.
				if f := _stat(ctx, joinedSym); f.exists() {
					// We stay entirely in the Walled Garden!
					return searched_path{sym: joinedSym, isDir: f._isDir}
				}
			}
		}
		return searched_path{sym: symEmpty, isDir: false} // Not found in search paths
    }
    return u.diagnostic.do(ctx, op)
}

