type workdir_sym Symbol

func new_universe(ii ...any) (ctx *universe) {
	ctx = &universe{
		launchTime: time.Now(),
		statcache:  make(map[Symbol]*filebase), // Upgraded to Symbol keys for O(1) integer hashing
		scope:      new_scope(nil, nil, symUniverse),
		fset:       new_fileset(),
		workdir:    symBaseWorkDir,
	}

	cl := true
	for _, i := range ii {
		switch t := i.(type) {
		case  hooks:       ctx.hooks =  t
		case *hooks:       ctx.hooks = *t
		case  commandline: ctx.commandline, cl =  t, false
		case *commandline: ctx.commandline, cl = *t, false
		case  workdir_sym: ctx.workdir = Symbol(t)
		}
	}
	if cl { ctx.commandline = _commandline() }

	// Bootstrap top-level AST arguments
	ctx.scope.def(ctx, defVoid, symSMART, ease(ctx, os.Args[0]))
	ctx.scope.def(ctx, defVoid, symSMART_ARGS, ease(ctx, os.Args[1:]))

	// Pre-register all builtin functions
	for name, f := range builtins {
		_, alt := ctx.scope.builtin(ctx, name, f)
		if alt != nil {
			panic(fmt.Sprintf("builtin '%s' already defined", name))
		}
	}

	ctx.globe = &globe{
		scope:       new_scope(ctx.scope, nil, symGlobe),
		args:        make(map[Value][]Value),
		flagEntries: make(map[Symbol][]entry),
		loaded:      make(map[Symbol]*project),
	}

	var pos Pos = 0 // ctx._position()
	ctx.globe.os    = ctx.globe.def(ctx, defVoid, symDotOS, _rw(pos, runtime.GOOS))
	ctx.globe.mode  = ctx.globe.def(ctx, defVoid, symDotMode, _null(pos))
	ctx.globe.goals = ctx.globe.def(ctx, defVoid, symDotGoals, _none(pos))

	// Pre-allocate to prevent heap thrashing during directory walk
	var paths = make(searchlist, 0, 4)

	// == Hermetic Test Isolation ==
	if checkpoints {
		paths = append(paths, __symPathJoin(ctx.workdir, intern("testdata"), symDotSmart, symModules))
	} else {
		walkSmartBaseDirs(ctx, ctx.workdir, func(s Symbol) bool {
			// FIXME: if baseTmpPath == symEmpty { baseTmpPath = s }
			paths = append(paths, __symPathJoin(s, symDotSmart, symModules))
			return true
		})
	}

	// NOTE: string pathing retained here as it interacts with distribution prefixes
	prefix := ctx.prefix ; if prefix == "" { prefix = string(filepath.Separator) }
	usrLib := filepath.Join(prefix+"usr", "lib", "smart", "modules")
	
	// Intern the absolute cleaned string back into the Walled Garden!
	paths = append(paths, intern(filepath.Clean(usrLib)))

	// CRITICAL FIX: Allocate a perfectly sized Symbol array (not string)
	cache := make([]Symbol, 0, len(paths)+len(ctx.paths))
	ctx.paths = append(append(cache, paths...), ctx.paths...)

	// Load dynamic search directories
	// Passing `ctx` so loadSearchPaths can hit the VFS!
	for _, s := range paths {
		if t := loadSearchPaths(ctx, s); len(t) > 0 { ctx.paths = t }
	}

	// =================================================================
	// THE DOD FIX: Absolute Workspace Masking Eradication!
	// If `_commandline()` or `loadSearchPaths()` implicitly injected `/Volumes/workspace`
	// into `ctx.paths`, we mathematically eradicate it here. We only allow
	// paths that explicitly end in the target modules directory.
	// =================================================================
	var hermeticPaths searchlist
	for _, p := range ctx.paths {
		strPath := p.String()
		if strings.HasSuffix(strPath, filepath.Join(".smart", "modules")) || strings.HasSuffix(strPath, filepath.Join("smart", "modules")) {
			hermeticPaths = append(hermeticPaths, p)
		}
	}
	ctx.paths = hermeticPaths

	return ctx
}

func cpu_profile(ctx Context, name string, heap ...bool) func() {
    var fn string
    if filepath.IsAbs(name) {
		fn = name
	} else if m := _universe(ctx).globe.main; m == nil {
		erro(ctx, "%s: main project is nil", name, unwind{})
	} else if f := m.tempfile(ctx, name); f == nil {
        fn = filepath.Join(symBaseWorkDir.String(), name)
    } else {
        fn = f.fullname().String()
    }

    f, e := os.Create(fn)
    if e != nil {
        erro(ctx, "%s", ts(e), unwind{})
    } else if e = pprof.StartCPUProfile(f); e != nil {
        erro(ctx, "%s", ts(e), unwind{})
    }
    return func() { if f != nil {
        if e != nil { pprof.StopCPUProfile() }
        if heap != nil && heap[0] { runtime.GC() // update memory statistics
            if e = pprof.WriteHeapProfile(f); e != nil {
                erro(ctx, "WriteHeapProfile: %v", e, unwind{})
            }
        }
        f.Close()
    }}
}

func heap_profile(ctx Context, name string) func() {
    var fn string
    if filepath.IsAbs(name) {
		fn = name
	} else if m := _universe(ctx).globe.main; m == nil {
		erro(ctx, "%s: main project is nil", name, unwind{})
	} else if f := m.tempfile(ctx, name); f == nil {
        fn = filepath.Join(symBaseWorkDir.String(), name)
    } else {
        fn = f.fullname().String()
    }

    f, e := os.Create(fn)
    if e != nil {
        erro(ctx, "%s", ts(e), unwind{})
    }
    return func() { if f != nil {
        if e != nil { pprof.StopCPUProfile() }
        runtime.GC() // update memory statistics

		e = pprof.WriteHeapProfile(f)
        f.Close()

        if e != nil {
            erro(ctx, "%v", ts(e), unwind{})
        }
    }}
}

func updateGoal(ctx Context, goal Value, args []Value) (result []Value) {
    switch g := goal.(type) {
    case *rule:
        var ok bool
        if result, ok = execute_entry(ctx, g, args...); !ok {
            erro(ctx, "update '%v' failed", g)
        }
    default:
        erro(ctx, "not an entry: %v", ts(goal, ctx))
    }
    return
}

func (u *universe) load(ctx Context) {
	if u.traceLaunch { defer un(l_trace(l_launch, "universe.load")) }

	if false { loadGrepCache(ctx) }

	// 1. VFS Pre-Warm / Sanity Check (Replaces dead os.Stat code)
	// We use pure Walled Garden pathing and cache lookups!
	if mainSym := _stat(ctx, __symPathJoin(u.workdir, intern(mainFileName))); mainSym == nil || !mainSym.exists() {
		if deprSym := _stat(ctx, __symPathJoin(u.workdir, intern(deprFileName))); deprSym == nil || !deprSym.exists() {
			// Do whatever the original intent of the dead code was, 
			// or just let u.globe.top.directory handle the failure gracefully!
		}
	}

	top := compiler{term: &term{ctx, u.globe.scope} }
	top.parseArgs(ctx, os.Args[1:])

	if u.profile {
		// 2. The Airlock: Extract the string exactly once for physical OS file creation
		cpuProfStr := __symPathJoin(u.workdir, intern("load.cpu.auto.prof")).String()
		f, e := os.Create(cpuProfStr)
		if e != nil {
			erro(ctx, "%v", e, unwind{})
			return
		} else if e := pprof.StartCPUProfile(f); e != nil {
			erro(ctx, "could not start CPU profile: %v", e, unwind{})
			return
		}
		
		defer func() {
			pprof.StopCPUProfile()

			f.Close()

			memProfStr := __symPathJoin(u.workdir, intern("load.mem.auto.prof")).String()
			f, e = os.Create(memProfStr)
			if e != nil {
				erro(ctx, "%v", e, unwind{})
			}

			runtime.GC() // update memory statistics

			e = pprof.WriteHeapProfile(f)
			if f.Close(); e != nil {
				erro(ctx, "could not write memory profile: %v", e, unwind{}) // Fixed error message
			}
		}()
	}

	// 3. String Unpacking for Terminal Output
	if u.verboseImport { prompt(ctx, "┌→%s\n", u.workdir.String()) }

	defer func(t time.Time) {
		// 4. Idiomatic time.Since replaces time.Now().Sub
		if d := time.Since(t); u.verboseImport {
			var name Symbol
			if p := top.project; p != nil { name = p.name }
			prompt(ctx, "└·%s … (%s)\n", name.String(), d)
		} else if false && u.slow < d {
			// Using pure Symbol for Context tagging!
			debug(pc(ctx, u.workdir), "slow loading (%v)!!\n", d)
		}
	} (time.Now())

	// 5. Zero-Allocation Path Resolution
	spec := __symPathRel(symBaseWorkDir, u.workdir)
	top.directory(top.term, spec, u.workdir)

	if false && top.project == nil {
		erro(pc(ctx,u.workdir), "%v: no project loaded, %s", spec, top.scope, callstack{num:16}, unwind{})
	}
	if u.globe.main == nil {
		erro(pc(ctx,u.workdir), "main project is nil", callstack{num:16}, unwind{})
	}
	return
}

func (u *universe) run() (result []Value) {
	if u.noRun { return }

	var main = u.globe.main
	if main == nil {
		erro(u, "no targets to update `%v`", u.globe.goals, unwind{})
		return
	}

	var ctx Context = closure_with(u, main.scope)
	if u.verbose { debug(ctx, "goal: %v", main) }

	main.removeTempSubdirs(ctx)

	if u.profile || u.cpuProfile != "" {
		var name = u.cpuProfile
		if name == "" { name = "cpu.profile" }
		defer cpu_profile(ctx, name, true)()
	}
	if u.profile || u.memProfile != "" {
		var name = u.memProfile
		if name == "" { name = "mem.profile" }
		defer heap_profile(ctx, name)()
	}

	var done bool
	for _, flag := range u.globe.flags {
		if u.verboseExecFlags { info(ctx, "%v", flag) }

		var s = __symbol(ctx, flag.Value)
		var args, _ = u.globe.args[flag]
		var entries, _ = u.globe.flagEntries[s]
		for _, entry := range entries {
			if u.verboseExecFlags { info(ctx, "%v", entry); flush(ctx) }

			res := entry.execute(ctx, args...)
			result = append(result, res...)
			done = true
		}
	}
	if done { return }

	var updated int
	var goals []Value
	var collect func(proj *project, vals []Value) bool
	collect = func(proj *project, vals []Value) bool {
		if len(vals) == 0 {
			if entry := proj.main; entry != nil {
				goals = append(goals, entry)
			}
			return true
		}
		for _, goal := range vals {
			switch t := goal.(type) {
			case *null, *none: // just ignore
			case *word:
				// NOTE: t.s is now a Symbol. If _entries expects a string, use t.s.String()
				// If _entries takes any/Value, t.s can be passed directly.
				if entries := proj._entries(ctx, t.s.String(), true); entries == nil {
					erro(ctx, "no such entry `%s`", t.s)
					return false
				} else {
					for _, entry := range entries { goals = append(goals, entry) }
				}
			case *delegate:
				var s = __string(ctx, t)
				if entries := proj._entries(ctx, s, true); entries == nil {
					erro(ctx, "no such entry `%s` (via `%v`)", s, t)
					return false
				} else {
					for _, entry := range entries { goals = append(goals, entry) }
				}
			case flag:
				var s = __string(ctx, t)
				if entries := proj._entries(ctx, s, true); entries == nil {
					erro(ctx, "no such entry `%s` (via `%v`)", s, t)
					return false
				} else {
					for _, entry := range entries { goals = append(goals, entry) }
				}
			case *argumented:
				{
					var (
						sStr = __string(ctx, t.Value)
						sSym = intern(sStr) // CRITICAL FIX: Cross into integer domain!
						args = merge(t.args...)
						found int
					)
					for _, p := range u.globe.loaded {
						// Fast O(1) integer matching!
						if p.name == sSym || p.spec == sSym {
							found += 1
							if !collect(p, args) { return false }
						}
					}
					if found == 0 {
						erro(ctx, `"%s" not loaded: %v`, sStr, args)
						return false
					}
				}
			default:
				erro(ctx, "%v: unknown target: %v (%s)", proj, goal, typeof(goal))
				return false
			}
		}
		return true
	}

	if collect(main, merge(u.globe.goals.value)) {
		if len(goals) == 0 {
			if entry := main.main; entry != nil {
				goals = append(goals, entry)
			}
		}
		for _, goal := range goals {
			args, _ := u.globe.args[goal]
			result = append(result, updateGoal(ctx, goal, args)...)
			updated += 1
		}
	}
	return
}

// A globe represents a global execution context.
type globe struct {
    *scope

    main *project
    loaded map[Symbol]*project // full pathname -> project

    args map[Value][]Value
    flagEntries map[Symbol][]entry
    flags []flag
    pairs []*pair

    os, goals, mode *def
}

func (g *globe) SetScopeOuter(scope *scope) { scope.outer = g.scope }
func (g *globe) AddFlagEntry(name Symbol, entry entry) {
    flags, _ := g.flagEntries[name]
    flags = append(flags, entry)
    g.flagEntries[name] = flags
    return
}

