func _bases(n int, s string, a ...any) (d, b string) {
	d, b = filepath.Dir(s), filepath.Base(s)
	if d == "" || d == "." {
		return
	}

	var k = 1

	// 1. Process the explicit depth 'n' unconditionally
	for i := n - k; i > 0; i -= 1 {
		if d == "/" || d == "." || d == "" { break }
		b = filepath.Join(filepath.Base(d), b)
		d = filepath.Dir(d)
		k += 1
	}

	// 2. Process optional string boundaries or boolean prefixing
	if a != nil {
		for _, arg := range a {
			switch t := arg.(type) {
			case bool:
				if filepath.IsAbs(d) {
					b = filepath.Join(d, b)
				} else if t {
					b = filepath.Join("…", b)
				}
			case string:
				for d != "/" && d != "." && d != "" && len(d)+len(b) < len(s) {
					k += 1
					if base := filepath.Base(d); base == t {
						d = filepath.Dir(d)
						break
					} else {
						b = filepath.Join(base, b)
						d = filepath.Dir(d)
					}
				}
			}
		}
	}
	return
}

func bases(n int, s string, a ...any) (b string) {
	_, b = _bases(n, s, a...)
	return
}

type __bases struct { builtinbase ; n int `num,size,count` }
func (ctx *__bases) do(c Context, op any) any {
	switch t := op.(type) {
	case inner_cast: return &ctx.builtinbase
	case dynamic_cast: return t.ctx(ctx, &ctx.builtinbase)
	}
	return ctx.builtinbase.do(c, op)
}
func (ctx *__bases) x() any {
	var vals []Value
	
	for _, a := range ctx.a {
		var sym Symbol

		// 1. Enter the Symbol Domain securely
		if ctx.fullname {
			sym, _ = fullname_sym(ctx, a)
		} else {
			sym = __symbol(ctx, a)
		}

		if sym == symEmpty {
			continue
		}

		// 2. Pure CPU-Register Path Math!
		// No string allocation, no filepath.Dir, no os.Stat.
		baseSym := __symNBase(ctx.n, sym)
		
		if baseSym == symEmpty {
			continue
		}

		// 3. O(1) AST Construction
		seq := getSymSeq(baseSym)
		
		if len(seq) == 0 {
			// Fast Path: It's a primitive SymRaw or SymEph (no slashes)
			vals = append(vals, _word(a.Pos(), baseSym))
		} else {
			// Slow Path: It's a SymSeq. We just extract the non-slash integer IDs!
			// This perfectly mimics strings.Split without allocating a string array!
			var p = new(path)
			for _, part := range seq {
				if part != symSlash && part != symEmpty {
					p.elems = append(p.elems, _word(a.Pos(), part))
				}
			}
			
			// Edge Case: If the sequence somehow only had one valid part after filtering
			if len(p.elems) == 1 {
				vals = append(vals, p.elems[0])
			} else {
				vals = append(vals, p)
			}
		}
	}
	return vals
}

