func readDirNames(ctx Context, sd string, errorMissing bool) (names []string) {
	if false {
		if f, err := os.Stat(sd); err != nil {
			if errorMissing {
				erro(ctx, "%v", err)
			}
			return
		} else if !f.IsDir() {
			erro(ctx, "not dir: %v", sd)
			return
		}
	}

	// Use os.ReadDir (Go 1.16+) instead of os.Open + Readdirnames.
	// It is faster and gives us DirEntry, which knows IsDir() without extra syscalls.
	entries, err := os.ReadDir(sd)

	if err != nil {
		if errorMissing { erro(ctx, "readdir: %v", err) }
		return
	}

	names = make([]string, 0, len(entries))

	for _, entry := range entries {
		if name := entry.Name(); entry.IsDir() {
			// Directories heavily repeat (src, bin, pkg, internal). Intern them!
			names = append(names, name)
		} else {
			// Files are often unique artifacts (obj_123.o). Leave them raw to protect GC.
			// Optional: You can explicitly intern safe, known file types here if desired:
			// if strings.HasSuffix(name, ".smart") { name = intern(name) }

			names = append(names, name)
		}
	}
	return
}

// stepPattern advances the AST pattern by one directory level safely in the pure integer domain.
func stepPattern(ctx Context, pat Value, nameSym Symbol) (nextPats []Value) {
	if l, ok := pat.(*list); ok {
		for _, e := range l.elems {
			nextPats = append(nextPats, stepPattern(ctx, e, nameSym)...)
		}
		return
	}

	if p, ok := pat.(*path); ok {
		if len(p.elems) == 0 { return }
		first := p.elems[0]

		// THE DOD FIX: Use `_pathSym` to evaluate the local segment!
		// This guarantees `nameSym` (like "a.def.am") is mathematically 
		// shattered and grouped exactly like the VFS directory walker!
		localVal := _pathSym(p.Pos(), nameSym)

		if isMultiWildcard(first) {
			// ** spans directories, so it must remain in the pattern for children
			nextPats = append(nextPats, pat)

			// ** can also consume 0 segments, so we check if the NEXT element matches this directory
			if len(p.elems) > 1 {
				okMatch, _, rem, _ := match(ctx, p.elems[1], localVal)
				if okMatch && (rem == nil || isEmpty(rem) || len(unpack(rem)) == 0) {
					if len(p.elems) > 2 {
						var nextPat Value
						if len(p.elems) == 3 {
							nextPat = p.elems[2]
						} else {
							nextPat = &path{elements{p.elems[2:]}}
						}
						nextPats = append(nextPats, nextPat)
					}
				}
			}
		} else {
			// Standard strict segment match
			okMatch, _, rem, _ := match(ctx, first, localVal)
			if okMatch && (rem == nil || isEmpty(rem) || len(unpack(rem)) == 0) {
				if len(p.elems) > 1 {
					var nextPat Value
					if len(p.elems) == 2 {
						nextPat = p.elems[1]
					} else {
						nextPat = &path{elements{p.elems[1:]}}
					}
					nextPats = append(nextPats, nextPat)
				}
			}
		}
		return
	}

	// Single segment global wildcards (like `**.h` without path wrapping)
	if isMultiWildcard(pat) {
		nextPats = append(nextPats, pat)
	}

	return
}

type wildcard_lock struct { pat Symbol }
type __wildcard struct {
	builtinbase
	includeMissing bool    `include,includemissing,include-missing,missing,all`
	ignoreMissing  bool    `ignore,ignoremissing,ignore-missing`
	errorMissing   bool    `err,error,errormissing,error-missing,no-missing`
	exclude        []Value `exclude,except,no,not`
	filetype       string  `type` // dir, file, etc.
	dir            string  `dir,directory`
	sort           bool    `sort`
	cache          bool    `cache` // The explicit caching opt-in flag!
	files          []*file
}
func (ctx *__wildcard) do(c Context, op any) any {
	switch t := op.(type) {
	case inner_cast: return &ctx.builtinbase
	case dynamic_cast: return t.ctx(ctx, &ctx.builtinbase)

	// =================================================================
	// THE DOD FIX: Native Ouroboros Shield!
	// If a nested wildcard queries this lock, check if the requested 
	// pattern matches any of the patterns THIS wildcard is already scanning.
	// =================================================================
	case wildcard_lock:
		for _, pat := range merge(ctx.a...) {
			if t.pat == __symbol(c, pat) { 
				return true 
			}
		}
	}
	return ctx.builtinbase.do(c, op)
}

func (ctx *__wildcard) collect(f *file) {
	if f != nil {
		if ctx.sort {
			i, found := slices.BinarySearchFunc(ctx.files, f, func(a, b *file) int {
				// ZERO-ALLOCATION ALPHABETICAL SORT!
				// .String() fetches the cached Walled Garden header without 
				// allocating a new string on the heap.
				strA := a.name.String()
				strB := b.name.String()

				switch {
				case strA < strB: return -1
				case strA > strB: return 1
				}
				return 0
			})
			if !found { ctx.files = slices.Insert(ctx.files, i, f) }
		} else {
			ctx.files = append(ctx.files, f)
		}
	}
}

func (ctx *__wildcard) directory(topDirSym Symbol, pats ...Value) {
	ne := ctx.includeMissing && !ctx.ignoreMissing

	pats = merge(pats...)

	// Pass Symbol IDs through the recursive walker instead of strings
	var walk func(Symbol, []Value)

	walk = func(dirSym Symbol, currentPats []Value) {
		fullDirSym := __symPathJoin(topDirSym, dirSym)

		// =================================================================
		// 1. Literal Prefix Lookahead
		// Eliminates O(N) OS directory scans and matchCompComp waste by 
		// extracting pure literal targets directly from the active patterns!
		// =================================================================
		var names []string
		var scanAll bool

		for _, pat := range currentPats {
			var first Value = pat

			// 1. AST Structural Peeling
			// If it's a path, we only care about the very first segment.
			if p, ok := pat.(*path); ok && len(p.elems) > 0 {
				first = p.elems[0]
			}

			// 2. Native Pattern Check
			// Let the AST engine tell us if this node contains globs (*, ?, etc.)
			if patterned(ctx, first) {
				scanAll = true
				break
			}

			// 3. Safe Literal Extraction
			// We are now mathematically guaranteed this is a pure literal node.
			// Evaluate ONLY this segment into a string, bypassing the rest of the path!
			s := __string(ctx, first)

			// dot-directories often require VFS/OS resolution fallbacks
			if s == "." || s == ".." {
				scanAll = true
				break
			}

			if s != "" {
				duplicate := false
				for _, n := range names {
					if n == s { duplicate = true; break }
				}
				if !duplicate { 
					names = append(names, s) 
				}
			}
		}

		if scanAll {
			// The Slow Path: Pull the full directory list from the OS
			names = readDirNames(ctx, fullDirSym.String(), ctx.errorMissing)
		} else if len(names) == 0 {
			// Nothing to look for at this depth.
			return
		}

	NamesLoop:
		for _, name := range names {
			// Re-enter the Walled Garden immediately
			nameSym := intern(name)

			dnSym := nameSym
			if dirSym != symEmpty && dirSym != symDot { 
				dnSym = __symPathJoin(dirSym, nameSym) // Pure sequence math!
			}

			// 2. Exclude Check
			dnVal := _pathSym(_pos(ctx), dnSym)

			for _, x := range ctx.exclude {
				if ok, _, rem, _ := match(ctx, x, dnVal); ok && (rem == nil || isEmpty(rem) || len(unpack(rem)) == 0) {
					continue NamesLoop
				}
			}

			// 3. Absolute Match Check
			matched := false
			for _, pat := range pats {
				full, _, rem, _ := match(ctx, pat, dnVal)

				// Safely accommodate empty slices yielded by deeply shattered path comparisons
				if full && (rem == nil || isEmpty(rem) || len(unpack(rem)) == 0) {
					matched = true
					break
				}
			}

			// 4. Step the patterns (The Semantic Branching Engine!)
			var nextPats []Value
			for _, pat := range currentPats {
				// stepPattern correctly yields branching states for `**`
				nextPats = append(nextPats, stepPattern(ctx, pat, nameSym)...)
			}

			// 5. Zero-Allocation Deduplication!
			// Because len(nextPats) is almost always tiny (1-4 elements), 
			// an inline double-loop is exponentially faster than allocating a hash map!
			if len(nextPats) > 1 {
				var unique []Value
				for _, np := range nextPats {
					duplicate := false
					for _, up := range unique {
						if eq(ctx, np, up) { 
							duplicate = true
							break
						}
					}
					if !duplicate {
						unique = append(unique, np)
					}
				}
				nextPats = unique
			}

			var f *file
			if matched || len(nextPats) > 0 {
				// Pure Integer Domain VFS hit! 
				// Bypasses the OS entirely if the literal target doesn't exist.
				f = _stat(ctx, dnSym, stat_dir{topDirSym}, stat_nonexist{ne})
				if f == nil || (f._mtime == 0 && !ne) { continue }
			}

			// 6. Collection 
			if matched && f != nil {
				validType := false
				switch strings.ToLower(ctx.filetype) {
				case "f", "file": validType = !f._isDir
				case "d", "dir":  validType = f._isDir
				default:          validType = true
				}

				if validType { ctx.collect(f) }
			}

			// 7. Recursive Descent
			if f != nil && f._isDir && len(nextPats) > 0 {
				walk(dnSym, nextPats)
			}
		}
	}

	walk(symEmpty, pats)
}

func (ctx *__wildcard) project(p *project, pats ...Value) {
	ne := ctx.includeMissing && !ctx.ignoreMissing
	for _, argPat := range pats {
		matchedFiles := unmap_files(ctx, p, argPat, nil)
		for _, matchedFile := range matchedFiles {
			for _, matchedPat := range matchedFile.filemap.patterns(ctx) {
				var searchVal = _if_cmp(ctx, cmpSmaller, argPat, matchedPat)
				var searchSym = __symbol(ctx, searchVal)
				var isSearchPat = patterned(ctx, searchVal)
				for _, matchedDir := range merge(expands(final{ctx}, matchedFile.filemap.paths...)...) {
					dirSym := __symbol(ctx, matchedDir) 

					// If dirSym is relative, e.g. "src", _stat(searchSym, stat_dir{dirSym}) is nil, but
					// "testdata/valcache/3/a/src" and the underneath files "x.h", "y.h", "z.h" exists.
					// THE DOD FIX: Anchor relative coordinates to absolute space!
					if !__symIsAbs(dirSym) { dirSym = __symPathJoin(p.absPath, dirSym) }
					if checkpoints { if !__symIsAbs(dirSym) {
						erro(ctx, "%v: !abs: %v → %v, %v", p.spec, ts(matchedDir,ctx), dirSym, searchVal)
					}}

					if searchSym.String() == "*.c" {
						var proj = matchedFile.project
						debug(ctx, "%v: %v %v %v %v %v %v", proj.name, matchedFile, argPat, matchedPat, searchVal, matchedDir, _project(ctx))
					}

					if isSearchPat {
						ctx.directory(dirSym, searchVal)
					} else {
						ctx.collect(_stat(ctx, searchSym, stat_dir{dirSym}, stat_nonexist{ne}))
					}
				}
			}
		}
	}
}

func (ctx *__wildcard) x() any {
	if len(ctx.exclude) > 0 {
		ctx.exclude = xmerge(final{ctx.Context}, ctx.exclude...)
	}

	pats := merge(ctx.a...)

	// ====================================================================
	// THE DOD FIX: Trigger the Shield!
	// Query the context chain (which traverses up to the outer wildcard).
	// If the outer wildcard intercepts this and returns true, we instantly 
	// abort to break the infinite VFS mapping feedback loop!
	// ====================================================================
	if false { for _, pat := range pats {
		if patSym := __symbol(ctx.Context, pat); patSym != symEmpty {
			if truly(ctx.Context, wildcard_lock{patSym}) {
				return nil 
			}
		}
	}}

	var cacheFile string
	var p = _project(ctx)
	var t0 = time.Now()

	// 1. Enter Walled Garden
	var ctxDirSym = symEmpty
	if ctx.dir != "" {
		ctxDirSym = intern(ctx.dir)
	}

	// ====================================================================
	// FAST PATH: Explicit Persistent Disk Caching
	// ====================================================================
	if ctx.cache && p != nil {
		var key = sha256.New()
		fmt.Fprintf(key, "dir:%s|type:%s|sort:%v|ex:%v", ctxDirSym.String(), ctx.filetype, ctx.sort, ctx.exclude)
		for _, pat := range pats {
			fmt.Fprintf(key, "|pat:%s", __string(ctx, pat))
		}

		var h hashbytes
		copy(h[:], key.Sum(nil))

		dir := hashDir(ctx, h[:])
		cacheFile = filepath.Join(dir, "globs", fmt.Sprintf("%x.txt", h))

		if b, err := os.ReadFile(cacheFile); err == nil {
			var cachedFiles []Value
			
			// DOD: Used bytes.Split to avoid allocating a massive []string slice!
			for _, pathBytes := range bytes.Split(b, []byte{'\n'}) {
				if len(pathBytes) == 0 { continue }

				pathSym := intern(string(pathBytes)) 
				
				var f *file
				if __symIsAbs(pathSym) {
					f = _stat(ctx, pathSym, stat_nonexist{true})
				} else {
					f = _stat(ctx, pathSym, stat_dir{ctxDirSym}, stat_nonexist{true})
				}

				if f == nil { f = p.file(ctx, pathSym.String()) }
				if f != nil { cachedFiles = append(cachedFiles, f) }
			}
			if false { debug(pc(ctx,cacheFile), "%v", time.Since(t0)) }
			return cachedFiles 
		}
	}

	// ====================================================================
	// SLOW PATH: OS File System Traversal
	// ====================================================================
	if ctxDirSym == symEmpty {
		ctx.project(p, pats...)
	} else {
		ctx.directory(ctxDirSym, pats...)
	}

	// ====================================================================
	// WRITE CACHE
	// ====================================================================
	if ctx.cache && cacheFile != "" && len(ctx.files) > 0 {
		if err := os.MkdirAll(filepath.Dir(cacheFile), 0700); err == nil {
			var sb strings.Builder
			for _, f := range ctx.files {
				if f.dir == ctxDirSym {
					// Pure integer join, eliminating filepath.Join
					subPathSym := __symJoin(f.sub, f.name)
					sb.WriteString(subPathSym.String())
				} else {
					sb.WriteString(f.fullname().String())
				}
				sb.WriteByte('\n')
			}
			os.WriteFile(cacheFile, []byte(sb.String()), 0644)
			if false { debug(pc(ctx,cacheFile), "%v", time.Since(t0)) }
		} else {
			erro(ctx, "failed to create cache dir: %v", err)
		}
	}

	return ctx.files
}

